"""Span-free investigation for the demo. The traced CLI path stays in agent.loop."""

from dataclasses import dataclass

from agent.decide import ReadResult, choose, outcome_after_reversal, render
from agent.result import AgentResult
from sim.constants import READ_OPS
from sim.errors import SimError
from sim.models import ChaosFlags, Scenario
from sim.world import World, open_world
from verifier.check import Verdict, verify

_CALLS = {
    "sender.get_debit": "get_debit",
    "sender.get_balance": "get_balance",
    "switch.get_status": "get_switch_status",
    "beneficiary.get_credit": "get_credit",
    "sender.reverse": "reverse",
}


@dataclass(frozen=True, slots=True)
class Review:
    v1: AgentResult
    v2: AgentResult
    v1_verdict: Verdict
    v2_verdict: Verdict

    @property
    def same_reply(self) -> bool:
        return self.v1_verdict.allowed and self.v1.reply == self.v2.reply


def review(scenario: Scenario, *, chaos: ChaosFlags | None = None) -> Review:
    """Run v1, and re-read the ledger when a reversal claim is unproved."""
    world = open_world(scenario, chaos=chaos)
    v1 = run_v1(world)
    v1_verdict = verify(v1)
    if v1_verdict.allowed or v1.outcome != "reversed":
        return Review(v1, v1, v1_verdict, v1_verdict)
    v2 = _reread(world, v1)
    return Review(v1, v2, v1_verdict, verify(v2))


def run_v1(world: World) -> AgentResult:
    order: list[str] = []
    reads: list[ReadResult] = []
    for op in READ_OPS:
        order.append(op)
        reads.append(call(world, op))
    packed = tuple(reads)
    action = choose(packed)
    reversal = None
    if action == "reverse":
        order.append("sender.reverse")
        reversal = call(world, "sender.reverse")
        outcome = outcome_after_reversal(reversal)
    else:
        outcome = action
    return AgentResult(
        seed=world.scenario.seed,
        outcome=outcome,
        reply=render(outcome, packed, reversal),
        reads=packed,
        reversal=reversal,
        tool_order=tuple(order),
        ledger_reversal_applied=world.ledger.reversal_applied,
    )


def call(world: World, op: str) -> ReadResult:
    try:
        value = getattr(world, _CALLS[op])()
    except SimError as exc:
        return ReadResult(op=op, ok=False, value=None, error=exc.code)
    return ReadResult(op=op, ok=True, value=value, error=None)


def _reread(world: World, v1: AgentResult) -> AgentResult:
    extra: list[ReadResult] = []
    order = list(v1.tool_order)
    for op in ("sender.get_debit", "sender.get_balance"):
        order.append(op)
        extra.append(call(world, op))
    reads = v1.reads + tuple(extra)
    debit = extra[0]
    if debit.ok and debit.value is not None and debit.value.get("reversal_applied") is True:
        outcome = "reversed"
    elif debit.ok and debit.value is not None:
        outcome = "reversal_not_posted"
    else:
        outcome = "incomplete"
    return AgentResult(
        seed=v1.seed,
        outcome=outcome,
        reply=render(outcome, reads, v1.reversal),
        reads=reads,
        reversal=v1.reversal,
        tool_order=tuple(order),
        ledger_reversal_applied=world.ledger.reversal_applied,
    )
=== agent/decide.py
"""Naive v1 policy. It trusts tool payloads and does not re-read after a reversal."""

from dataclasses import dataclass

from sim.constants import ESCALATION_LIMIT_KOBO
from sim.money import format_naira


@dataclass(frozen=True, slots=True)
class ReadResult:
    op: str
    ok: bool
    value: dict | None
    error: str | None


def choose(reads: tuple[ReadResult, ...]) -> str:
    indexed = {read.op: read for read in reads}
    debit = _payload(indexed.get("sender.get_debit"))
    switch = _payload(indexed.get("switch.get_status"))
    credit = _payload(indexed.get("beneficiary.get_credit"))
    amount = _amount(debit, switch, credit)
    if amount is not None and amount > ESCALATION_LIMIT_KOBO:
        return "escalate_over_limit"
    if switch is not None and switch.get("status") == "pending":
        return "pending"
    if debit is not None and debit.get("reversal_applied") is True:
        return "already_reversed"
    if debit is None or switch is None or credit is None:
        return "incomplete"
    debited = bool(debit.get("debited"))
    status = switch.get("status")
    credited = bool(credit.get("credited"))
    if not debited and not credited and status == "failed":
        return "no_debit"
    if debited and status == "failed" and not credited:
        return "reverse"
    if debited and status == "success" and credited:
        return "credited"
    return "escalate_conflict"


def outcome_after_reversal(reversal: ReadResult) -> str:
    if reversal.ok and reversal.value is not None and reversal.value.get("status") == "reversed":
        return "reversed"
    return "incomplete"


def render(
    outcome: str,
    reads: tuple[ReadResult, ...],
    reversal: ReadResult | None,
) -> str:
    indexed = {read.op: read for read in reads}
    debit = _payload(indexed.get("sender.get_debit"))
    switch = _payload(indexed.get("switch.get_status"))
    credit = _payload(indexed.get("beneficiary.get_credit"))
    if outcome == "credited":
        assert debit is not None and switch is not None and credit is not None
        return (
            f"{debit['transfer_id']} was credited. "
            f"{debit['bank']} debited account {debit['account']} "
            f"{format_naira(debit['amount_kobo'])} at {debit['debit_at']}. "
            f"The switch status is success as of {switch['updated_at']}. "
            f"{credit['bank']} credited account {credit['account']} at {credit['credit_at']}."
        )
    if outcome == "reversed":
        assert reversal is not None and reversal.value is not None
        return (
            f"The reversal for {reversal.value['transfer_id']} was processed "
            f"at {reversal.value['reversed_at']}."
        )
    if outcome == "reversal_not_posted":
        assert reversal is not None and reversal.value is not None and debit is not None
        return (
            f"The reversal tool reported success for {reversal.value['transfer_id']} "
            f"at {reversal.value['reversed_at']}. "
            f"The ledger read at {debit['read_at']} still shows the debit open."
        )
    if outcome == "already_reversed":
        assert debit is not None
        return (
            f"The debit for {debit['transfer_id']} was already reversed at {debit['reversed_at']}."
        )
    if outcome == "pending":
        assert switch is not None
        return (
            f"The switch still shows {switch['transfer_id']} as pending "
            f"as of {switch['updated_at']}."
        )
    if outcome == "escalate_conflict":
        assert switch is not None and credit is not None
        posted = "credited" if credit["credited"] else "not credited"
        return (
            f"The records for {switch['transfer_id']} disagree. "
            f"The switch status is {switch['status']} and the beneficiary was {posted}."
        )
    if outcome == "escalate_over_limit":
        amount = _amount(debit, switch, credit)
        transfer_id = _transfer_id(debit, switch, credit)
        assert amount is not None and transfer_id is not None
        return (
            f"{format_naira(amount)} is over the {format_naira(ESCALATION_LIMIT_KOBO)} limit, "
            f"so {transfer_id} was not resolved."
        )
    if outcome == "no_debit":
        assert debit is not None
        return f"{debit['transfer_id']} was not debited, and the beneficiary was not credited."
    transfer_id = _transfer_id(debit, switch, credit) or "this transfer"
    failures = [f"{read.op} failed with {read.error}" for read in reads if not read.ok]
    if reversal is not None and not reversal.ok:
        failures.append(f"{reversal.op} failed with {reversal.error}")
    if reversal is not None and reversal.ok and reversal.value is not None:
        if reversal.value.get("status") == "rejected":
            failures.append(f"sender.reverse was rejected: {reversal.value.get('reason')}")
    detail = "; ".join(failures) if failures else "a required record was missing"
    return f"I could not resolve {transfer_id}. {detail}."


def _payload(read: ReadResult | None) -> dict | None:
    if read is None or not read.ok or read.value is None:
        return None
    return read.value


def _amount(*payloads: dict | None) -> int | None:
    for payload in payloads:
        if payload is None:
            continue
        amount = payload.get("amount_kobo")
        if type(amount) is int:
            return amount
    return None


def _transfer_id(*payloads: dict | None) -> str | None:
    for payload in payloads:
        if payload is None:
            continue
        transfer_id = payload.get("transfer_id")
        if isinstance(transfer_id, str) and transfer_id:
            return transfer_id
    return None
=== agent/loop.py
"""One complaint in, one reply out. v1 does not re-read the ledger after a reversal."""

import neatlogs

from agent.decide import ReadResult, choose, outcome_after_reversal, render
from agent.prompt import PROMPT_VERSION
from agent.result import AgentResult
from agent.tools import ToolFailure, Toolbelt
from sim.constants import READ_OPS
from sim.models import ChaosFlags, Scenario
from sim.world import World, open_world

_READS = {
    "sender.get_debit": "get_debit",
    "sender.get_balance": "get_balance",
    "switch.get_status": "get_switch_status",
    "beneficiary.get_credit": "get_credit",
}


def investigate(scenario: Scenario, *, chaos: ChaosFlags | None = None) -> AgentResult:
    return _investigate(scenario.seed, open_world(scenario, chaos=chaos))


@neatlogs.span(
    kind="AGENT",
    name="receipts.investigate",
    version=PROMPT_VERSION,
    tags=[f"prompt:{PROMPT_VERSION}"],
    capture_input=False,
    capture_output=False,
)
def _investigate(seed: int, world: World) -> AgentResult:
    belt = Toolbelt(world)
    reads = tuple(_capture(op, getattr(belt, _READS[op])) for op in READ_OPS)
    action = choose(reads)
    reversal = None
    if action == "reverse":
        reversal = _capture("sender.reverse", belt.reverse)
        outcome = outcome_after_reversal(reversal)
    else:
        outcome = action
    return AgentResult(
        seed=seed,
        outcome=outcome,
        reply=render(outcome, reads, reversal),
        reads=reads,
        reversal=reversal,
        tool_order=tuple(belt.order),
        ledger_reversal_applied=world.ledger.reversal_applied,
    )


def _capture(op: str, fn) -> ReadResult:
    try:
        return ReadResult(op=op, ok=True, value=fn(), error=None)
    except ToolFailure as exc:
        return ReadResult(op=op, ok=False, value=None, error=exc.code)
=== agent/tools.py
"""Tool calls around one world. A raised tool error becomes a failed trace span."""

import neatlogs

from sim.errors import SimError
from sim.world import World


class ToolFailure(Exception):
    def __init__(self, op: str, code: str):
        self.op = op
        self.code = code
        super().__init__(f"{code} during {op}")


class Toolbelt:
    def __init__(self, world: World):
        self.world = world
        self.order: list[str] = []

    @neatlogs.span(
        kind="TOOL",
        name="sender.get_debit",
        tool_name="sender.get_debit",
        capture_input=False,
    )
    def get_debit(self) -> dict:
        return self._call("sender.get_debit", self.world.get_debit)

    @neatlogs.span(
        kind="TOOL",
        name="sender.get_balance",
        tool_name="sender.get_balance",
        capture_input=False,
    )
    def get_balance(self) -> dict:
        return self._call("sender.get_balance", self.world.get_balance)

    @neatlogs.span(
        kind="TOOL",
        name="switch.get_status",
        tool_name="switch.get_status",
        capture_input=False,
    )
    def get_switch_status(self) -> dict:
        return self._call("switch.get_status", self.world.get_switch_status)

    @neatlogs.span(
        kind="TOOL",
        name="beneficiary.get_credit",
        tool_name="beneficiary.get_credit",
        capture_input=False,
    )
    def get_credit(self) -> dict:
        return self._call("beneficiary.get_credit", self.world.get_credit)

    @neatlogs.span(
        kind="TOOL",
        name="sender.reverse",
        tool_name="sender.reverse",
        capture_input=False,
    )
    def reverse(self) -> dict:
        return self._call("sender.reverse", self.world.reverse)

    def _call(self, op: str, fn):
        self.order.append(op)
        try:
            return fn()
        except SimError as exc:
            raise ToolFailure(op, exc.code) from exc
