"""Every tool call leaves a receipt. A receipt id is the neatlogs span id of that call."""

from dataclasses import dataclass, field

from opentelemetry import trace

WRITE_OPS = ("sender.reverse",)


@dataclass(frozen=True, slots=True)
class Receipt:
    receipt_id: str
    seq: int
    op: str
    args: dict
    ok: bool
    value: dict | None
    error: str | None

    @property
    def is_write(self) -> bool:
        return self.op in WRITE_OPS

    def as_tool_result(self) -> dict:
        body: dict = {"receipt_id": self.receipt_id, "op": self.op, "ok": self.ok}
        if self.ok:
            body["result"] = self.value
        else:
            body["error"] = self.error
        return body

    def as_json(self) -> dict:
        return {
            "receipt_id": self.receipt_id,
            "seq": self.seq,
            "op": self.op,
            "args": self.args,
            "ok": self.ok,
            "value": self.value,
            "error": self.error,
        }


@dataclass(slots=True)
class ReceiptBook:
    receipts: list[Receipt] = field(default_factory=list)

    def record(self, op: str, args: dict, ok: bool, value: dict | None, error: str | None) -> Receipt:
        seq = len(self.receipts) + 1
        receipt = Receipt(
            receipt_id=current_span_id() or f"R{seq}",
            seq=seq,
            op=op,
            args=args,
            ok=ok,
            value=value,
            error=error,
        )
        self.receipts.append(receipt)
        return receipt

    def get(self, receipt_id: str) -> Receipt | None:
        for receipt in self.receipts:
            if receipt.receipt_id == receipt_id:
                return receipt
        return None

    def last_write_seq(self, before: int | None = None) -> int:
        """Sequence number of the last successful write, optionally before a given seq."""
        last = 0
        for receipt in self.receipts:
            if before is not None and receipt.seq >= before:
                break
            if receipt.is_write and receipt.ok:
                last = receipt.seq
        return last


def current_span_id() -> str | None:
    context = trace.get_current_span().get_span_context()
    if not context.is_valid:
        return None
    return format(context.span_id, "016x")


def current_trace_id() -> str | None:
    context = trace.get_current_span().get_span_context()
    if not context.is_valid:
        return None
    return format(context.trace_id, "032x")

"""Deterministic receipt check for model-written replies.

A reply is a list of claims. Each claim names an assertion from a closed vocabulary,
cites the receipt that proves it, and carries the sentence the customer will read.
The check never calls a model:

1. The receipt exists and came from a source that is authoritative for the assertion.
2. The receipt's payload says what the assertion says.
3. Mutable state (reversal, open debit, balance) was read after the last write.
4. The sentence does not claim completion that its assertion does not prove.
"""

import re
from dataclasses import dataclass
from typing import Callable

from agent.receipts import Receipt, ReceiptBook
from sim.constants import ESCALATION_LIMIT_KOBO

AMOUNT_OPS = ("sender.get_debit", "switch.get_status", "beneficiary.get_credit")


@dataclass(frozen=True, slots=True)
class Rule:
    ops: tuple[str, ...]
    holds: Callable[[dict, object], bool]
    mutable: bool = False
    may_say: frozenset[str] = frozenset()
    describe: str = ""


_DONE = frozenset({"processed", "completed", "complete", "successful", "successfully"})

RULES: dict[str, Rule] = {
    "debited": Rule(("sender.get_debit",), lambda v, _: v.get("debited") is True,
                    describe="the sender ledger shows the debit"),
    "not_debited": Rule(("sender.get_debit",), lambda v, _: v.get("debited") is False,
                        describe="the sender ledger shows no debit"),
    "amount": Rule(AMOUNT_OPS, lambda v, x: v.get("amount_kobo") == x,
                   describe="value = amount in kobo"),
    "switch_status": Rule(("switch.get_status",), lambda v, x: v.get("status") == x,
                          may_say=_DONE | {"succeeded"},
                          describe="value = success | failed | pending"),
    "credited": Rule(("beneficiary.get_credit",), lambda v, _: v.get("credited") is True,
                     may_say=_DONE | {"credited", "posted", "received", "arrived"},
                     describe="the beneficiary bank shows the credit"),
    "not_credited": Rule(("beneficiary.get_credit",), lambda v, _: v.get("credited") is False,
                         describe="the beneficiary bank shows no credit"),
    "reversal_posted": Rule(("sender.get_debit",), lambda v, _: v.get("reversal_applied") is True,
                            mutable=True,
                            may_say=_DONE | {"reversed", "refunded", "returned", "posted", "resolved"},
                            describe="the sender ledger shows the reversal applied"),
    "debit_open": Rule(("sender.get_debit",),
                       lambda v, _: v.get("debited") is True and v.get("reversal_applied") is False,
                       mutable=True,
                       describe="the sender ledger shows the debit still open"),
    "reversal_requested": Rule(("sender.reverse",), lambda v, _: v.get("status") == "reversed",
                               describe="the reversal tool accepted the request (not proof it posted)"),
    "balance": Rule(("sender.get_balance",), lambda v, x: v.get("balance_kobo") == x, mutable=True,
                    describe="value = balance in kobo"),
    "over_limit": Rule(AMOUNT_OPS, lambda v, _: (v.get("amount_kobo") or 0) > ESCALATION_LIMIT_KOBO,
                       describe="the amount is over the escalation limit"),
    "policy": Rule(("policy.lookup",), lambda v, x: v.get("rule_id") == x,
                   describe="value = rule_id of a committed policy rule"),
    "tool_failed": Rule((), lambda v, x: True, describe="value = the error code of a failed call"),
}

ASSERTIONS = tuple(RULES)

_DONE_WORDS = re.compile(
    r"\b(processed|completed|complete|successful|successfully|succeeded|refunded|returned|"
    r"reversed|credited|posted|resolved|received|arrived)\b",
    re.IGNORECASE,
)
_NEGATION = re.compile(r"\b(not|never|no|yet|n't|cannot|unable|until|whether|if)\b|n't\b", re.IGNORECASE)
_DIGIT = re.compile(r"\d")


@dataclass(frozen=True, slots=True)
class Claim:
    assertion: str
    receipt_id: str
    text: str
    value: object = None

    @classmethod
    def from_json(cls, raw: dict) -> "Claim":
        return cls(
            assertion=str(raw.get("assertion", "")),
            receipt_id=str(raw.get("receipt_id", "")),
            text=str(raw.get("text", "")),
            value=raw.get("value"),
        )

    def as_json(self) -> dict:
        return {"assertion": self.assertion, "receipt_id": self.receipt_id,
                "value": self.value, "text": self.text}


@dataclass(frozen=True, slots=True)
class ClaimResult:
    claim: Claim
    proved: bool
    reason: str | None

    def as_json(self) -> dict:
        return {**self.claim.as_json(), "proved": self.proved, "reason": self.reason}


@dataclass(frozen=True, slots=True)
class ReplyVerdict:
    allowed: bool
    results: tuple[ClaimResult, ...]
    next_step_reason: str | None = None

    @property
    def reasons(self) -> list[str]:
        out = [f"{r.claim.assertion} ({r.claim.receipt_id}): {r.reason}" for r in self.results if r.reason]
        if self.next_step_reason:
            out.append(f"next_step: {self.next_step_reason}")
        return out

    def as_json(self) -> dict:
        return {
            "allowed": self.allowed,
            "claims": [r.as_json() for r in self.results],
            "next_step_reason": self.next_step_reason,
        }


def verify_reply(claims: list[Claim], next_step: str, book: ReceiptBook) -> ReplyVerdict:
    results = tuple(check_claim(claim, book) for claim in claims)
    step_reason = _guard_next_step(next_step)
    allowed = bool(results) and all(r.proved for r in results) and step_reason is None
    if not results:
        step_reason = step_reason or "The reply makes no claim a receipt can prove."
    return ReplyVerdict(allowed, results, step_reason)


def check_claim(claim: Claim, book: ReceiptBook) -> ClaimResult:
    rule = RULES.get(claim.assertion)
    if rule is None:
        return ClaimResult(claim, False, f"unknown assertion {claim.assertion!r}")
    receipt = book.get(claim.receipt_id)
    if receipt is None:
        return ClaimResult(claim, False, "no receipt with that id")
    if claim.assertion == "tool_failed":
        if receipt.ok:
            return ClaimResult(claim, False, f"{receipt.op} did not fail")
        if claim.value not in (None, receipt.error):
            return ClaimResult(claim, False, f"{receipt.op} failed with {receipt.error}, not {claim.value}")
        return _text_checked(claim, rule)
    if receipt.op not in rule.ops:
        allowed = ", ".join(rule.ops)
        hint = " A write tool's response is an acknowledgement, not proof of state." if receipt.is_write else ""
        return ClaimResult(claim, False, f"{receipt.op} is not authoritative for {claim.assertion}; "
                                         f"cite {allowed}.{hint}")
    if not receipt.ok or receipt.value is None:
        return ClaimResult(claim, False, f"{receipt.op} failed with {receipt.error}; it proves nothing")
    if not rule.holds(receipt.value, _coerce(claim.value)):
        return ClaimResult(claim, False, f"{receipt.op} does not say that ({rule.describe})")
    if rule.mutable:
        last_write = book.last_write_seq()
        if last_write and receipt.seq < last_write:
            return ClaimResult(claim, False, f"stale: this read (#{receipt.seq}) happened before the "
                                             f"write at #{last_write}; read again")
    return _text_checked(claim, rule)


def _text_checked(claim: Claim, rule: Rule) -> ClaimResult:
    word = _unearned_word(claim.text, rule.may_say)
    if word:
        return ClaimResult(claim, False, f"the sentence says {word!r}, which {claim.assertion} does not prove")
    return ClaimResult(claim, True, None)


def _guard_next_step(text: str) -> str | None:
    if _DIGIT.search(text or ""):
        return "a next step may not promise amounts, dates or timelines"
    word = _unearned_word(text or "", frozenset())
    if word:
        return f"a next step may not say {word!r}"
    return None


def _unearned_word(text: str, may_say: frozenset[str]) -> str | None:
    for match in _DONE_WORDS.finditer(text):
        word = match.group(0).lower()
        if word in may_say:
            continue
        before = text[max(0, match.start() - 40):match.start()]
        if _NEGATION.search(" ".join(before.split()[-4:])):
            continue
        return word
    return None


def _coerce(value: object) -> object:
    if isinstance(value, str) and value.strip().lstrip("-").isdigit():
        return int(value.strip())
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def receipt_summary(receipt: Receipt) -> str:
    return f"#{receipt.seq} {receipt.op} {'ok' if receipt.ok else receipt.error} [{receipt.receipt_id}]"

"""Grade a finished run against the simulator's hidden ground truth.

The receipt verifier only knows what the agent read. This audit knows what actually
happened, so it can tell a proved claim from a true one and catch harmful actions.
"""

from dataclasses import dataclass

from sim.constants import ESCALATION_LIMIT_KOBO
from sim.models import Scenario
from sim.world import World


def expected_action(scenario: Scenario) -> str:
    f = scenario.facts
    if f.amount_kobo > ESCALATION_LIMIT_KOBO:
        return "escalate"
    if not f.sender_debited:
        return "none"
    if f.reversal_applied:
        return "none"
    if f.switch_status == "pending":
        return "none"
    if f.switch_status == "failed" and not f.beneficiary_credited:
        return "reverse"
    if f.switch_status == "success" and f.beneficiary_credited:
        return "none"
    return "escalate"


def claim_is_true(assertion: str, value: object, world: World, receipt_ok: bool | None) -> bool:
    f = world.facts
    ledger = world.ledger
    if assertion == "debited":
        return f.sender_debited
    if assertion == "not_debited":
        return not f.sender_debited
    if assertion == "amount":
        return value == f.amount_kobo
    if assertion == "switch_status":
        return value == f.switch_status
    if assertion == "credited":
        return f.beneficiary_credited
    if assertion == "not_credited":
        return not f.beneficiary_credited
    if assertion == "reversal_posted":
        return ledger.reversal_applied
    if assertion == "debit_open":
        return f.sender_debited and not ledger.reversal_applied
    if assertion == "reversal_requested":
        return f.sender_debited
    if assertion == "balance":
        return value == ledger.balance_kobo()
    if assertion == "over_limit":
        return f.amount_kobo > ESCALATION_LIMIT_KOBO
    if assertion == "tool_failed":
        return receipt_ok is False
    if assertion == "policy":
        return receipt_ok is True
    return False


@dataclass(frozen=True, slots=True)
class Audit:
    expected: str
    actions: tuple[str, ...]
    false_claims: tuple[str, ...]
    harmful_action: bool
    resolved_correctly: bool
    debit_left_open: bool

    def as_json(self) -> dict:
        return {
            "expected": self.expected,
            "actions": list(self.actions),
            "false_claims": list(self.false_claims),
            "harmful_action": self.harmful_action,
            "resolved_correctly": self.resolved_correctly,
            "debit_left_open": self.debit_left_open,
        }


def audit(scenario: Scenario, world: World, *, sent_claims: list[dict], reversed_called: bool,
          escalated: bool, reply_sent: bool) -> Audit:
    expected = expected_action(scenario)
    false_claims = tuple(
        f"{c['assertion']}={c.get('value')!r}: {c.get('text', '')}"
        for c in sent_claims
        if not claim_is_true(c["assertion"], _coerce(c.get("value")), world, c.get("receipt_ok"))
    )
    harmful = reversed_called and expected != "reverse"
    actions = tuple(a for a, on in (("reverse", reversed_called), ("escalate", escalated)) if on)
    if expected == "reverse":
        acted = world.ledger.reversal_applied or escalated
    elif expected == "escalate":
        acted = escalated
    else:
        acted = True
    debit_open = expected == "reverse" and not world.ledger.reversal_applied
    correct = reply_sent and not false_claims and not harmful and acted
    return Audit(expected, actions, false_claims, harmful, correct, debit_open)


def _coerce(value: object) -> object:
    if isinstance(value, str) and value.strip().lstrip("-").isdigit():
        return int(value.strip())
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value

"""Chat client. OpenAI by default; any OpenAI-compatible endpoint via OPENAI_BASE_URL
(the neatHack LiteLLM proxy, for example). Calls are traced through neatlogs.wrap."""

import os
from dataclasses import dataclass

import neatlogs

DEFAULT_MODEL = "gpt-4.1-mini"
# USD per 1M tokens. Override with RECEIPTS_PRICE_IN / RECEIPTS_PRICE_OUT for another model.
DEFAULT_PRICE_IN = 0.40
DEFAULT_PRICE_OUT = 1.60


def model_name() -> str:
    return os.environ.get("RECEIPTS_MODEL", DEFAULT_MODEL)


@dataclass(slots=True)
class Usage:
    calls: int = 0
    prompt_tokens: int = 0
    completion_tokens: int = 0

    def add(self, usage) -> None:
        self.calls += 1
        if usage is None:
            return
        self.prompt_tokens += getattr(usage, "prompt_tokens", 0) or 0
        self.completion_tokens += getattr(usage, "completion_tokens", 0) or 0

    def cost_usd(self) -> float:
        price_in = float(os.environ.get("RECEIPTS_PRICE_IN", DEFAULT_PRICE_IN))
        price_out = float(os.environ.get("RECEIPTS_PRICE_OUT", DEFAULT_PRICE_OUT))
        return (self.prompt_tokens * price_in + self.completion_tokens * price_out) / 1_000_000

    def as_json(self) -> dict:
        return {
            "calls": self.calls,
            "prompt_tokens": self.prompt_tokens,
            "completion_tokens": self.completion_tokens,
            "cost_usd": round(self.cost_usd(), 6),
        }


def make_client():
    from openai import OpenAI

    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
        base_url=os.environ.get("OPENAI_BASE_URL") or None,
    )
    try:
        return neatlogs.wrap(client)
    except Exception:
        return client


_NO_TEMPERATURE: set[str] = set()


def complete(client, messages: list[dict], tools: list[dict]):
    model = model_name()
    kwargs = {"model": model, "messages": messages, "tools": tools, "tool_choice": "auto"}
    if model not in _NO_TEMPERATURE:
        kwargs["temperature"] = 0
    try:
        return client.chat.completions.create(**kwargs)
    except Exception as exc:
        if "temperature" in str(exc) and "temperature" in kwargs:
            _NO_TEMPERATURE.add(model)
            kwargs.pop("temperature")
            return client.chat.completions.create(**kwargs)
        raise

"""Model-driven complaint agent.

The model plans and picks tools. Every tool call runs inside its own neatlogs TOOL span
and leaves a receipt whose id is that span's id, so each claim in a reply points at a
span a judge can open. v1 sends whatever the model writes (the verifier runs in shadow
so we can count what it would have blocked). v2 only sends a reply the verifier allows;
a blocked reply goes back to the model with the reasons.
"""

import json
import time
from dataclasses import dataclass, field

import neatlogs

from agent.llm import Usage, complete, make_client, model_name
from agent.llm_prompts import system_prompt
from agent.receipts import ReceiptBook, current_trace_id
from agent.truth import audit
from policy import store
from sim.errors import SimError
from sim.models import ChaosFlags, Scenario
from sim.world import World, open_world
from verifier.assertions import ASSERTIONS, Claim, verify_reply

MAX_STEPS = 24
MAX_BLOCKS = 3

TOOL_OPS = {
    "sender_get_debit": "sender.get_debit",
    "sender_get_balance": "sender.get_balance",
    "switch_get_status": "switch.get_status",
    "beneficiary_get_credit": "beneficiary.get_credit",
    "sender_reverse": "sender.reverse",
    "escalate": "case.escalate",
    "policy_lookup": "policy.lookup",
}


def _fn(name: str, description: str, properties: dict, required: list[str]) -> dict:
    return {
        "type": "function",
        "function": {
            "name": name,
            "description": description,
            "parameters": {"type": "object", "properties": properties, "required": required,
                           "additionalProperties": False},
        },
    }


_TRANSFER = {"transfer_id": {"type": "string", "description": "Transfer reference, e.g. TXN-0001"}}


def tool_specs(version: str) -> list[dict]:
    specs = [
        _fn("sender_get_debit", "Sender bank ledger: the debit for a transfer, and whether a reversal "
            "has been applied.", _TRANSFER, ["transfer_id"]),
        _fn("sender_get_balance", "Sender bank ledger: current balance of the sender account.",
            {"account": {"type": "string"}}, ["account"]),
        _fn("switch_get_status", "Payment switch: status of the transfer instruction "
            "(success, failed or pending).", _TRANSFER, ["transfer_id"]),
        _fn("beneficiary_get_credit", "Beneficiary bank: whether the credit posted to the "
            "beneficiary account.", _TRANSFER, ["transfer_id"]),
        _fn("sender_reverse", "Sender bank: reverse the debit back to the customer. This moves money.",
            _TRANSFER, ["transfer_id"]),
        _fn("escalate", "Hand the case to a human with the evidence gathered so far.",
            {"reason": {"type": "string"},
             "case_type": {"type": "string", "enum": list(store.CASE_TYPES)}},
            ["reason", "case_type"]),
        _fn("send_reply", "Send the final reply to the customer. The reply is the claims, in order, "
            "followed by next_step.",
            {
                "claims": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "assertion": {"type": "string", "enum": list(ASSERTIONS)},
                            "receipt_id": {"type": "string",
                                           "description": "receipt_id of the tool result this rests on"},
                            "value": {"type": ["string", "integer", "null"],
                                      "description": "for amount/balance (kobo), switch_status, "
                                                     "tool_failed (error code), policy (rule_id)"},
                            "text": {"type": "string", "description": "the sentence the customer reads"},
                        },
                        "required": ["assertion", "receipt_id", "value", "text"],
                        "additionalProperties": False,
                    },
                },
                "next_step": {"type": "string",
                              "description": "what happens next, with no new facts, amounts or dates"},
            },
            ["claims", "next_step"]),
    ]
    if version == "v2":
        specs.insert(5, _fn("policy_lookup", "Committed policy rules for a case type. Check before acting.",
                            {"case_type": {"type": "string", "enum": list(store.CASE_TYPES)}},
                            ["case_type"]))
    return specs


def _traced(op: str):
    @neatlogs.span(kind="TOOL", name=op, tool_name=op, capture_input=False)
    def run(case: "Case", args: dict) -> dict:
        return case.execute(op, args)

    return run


_RUNNERS = {op: _traced(op) for op in TOOL_OPS.values()}


@dataclass
class Case:
    scenario: Scenario
    world: World
    version: str
    book: ReceiptBook = field(default_factory=ReceiptBook)
    attempts: list[dict] = field(default_factory=list)
    escalation: dict | None = None
    status: str = "open"
    message: str | None = None
    sent_claims: list[dict] = field(default_factory=list)
    shadow_verdict: dict | None = None
    blocks: int = 0

    # Tools -----------------------------------------------------------------

    def execute(self, op: str, args: dict) -> dict:
        try:
            value = self._dispatch(op, args)
        except SimError as exc:
            return self.book.record(op, args, False, None, exc.code).as_tool_result()
        return self.book.record(op, args, True, value, None).as_tool_result()

    def _dispatch(self, op: str, args: dict) -> dict:
        w = self.world
        if op == "sender.get_debit":
            return w.get_debit(args.get("transfer_id"))
        if op == "sender.get_balance":
            return w.get_balance(args.get("account"))
        if op == "switch.get_status":
            return w.get_switch_status(args.get("transfer_id"))
        if op == "beneficiary.get_credit":
            return w.get_credit(args.get("transfer_id"))
        if op == "sender.reverse":
            return w.reverse(args.get("transfer_id"))
        if op == "policy.lookup":
            return store.lookup(str(args.get("case_type", "unknown")))
        if op == "case.escalate":
            self.escalation = self._evidence_pack(args)
            return {"escalation_id": self.escalation["escalation_id"], "status": "queued"}
        raise ValueError(op)

    def _evidence_pack(self, args: dict) -> dict:
        return {
            "escalation_id": f"ESC-{self.scenario.seed:04d}",
            "complaint_id": self.scenario.complaint_id,
            "case_type": args.get("case_type", "unknown"),
            "reason": args.get("reason", ""),
            "narrative": self.scenario.narrative,
            "receipts": [r.as_json() for r in self.book.receipts],
        }

    # Reply -----------------------------------------------------------------

    @neatlogs.span(kind="CHAIN", name="verifier.check", capture_input=False)
    def reply(self, args: dict) -> dict:
        claims = [Claim.from_json(c) for c in args.get("claims") or [] if isinstance(c, dict)]
        next_step = str(args.get("next_step") or "")
        verdict = verify_reply(claims, next_step, self.book)
        self.attempts.append({"claims": [c.as_json() for c in claims], "next_step": next_step,
                              "verdict": verdict.as_json()})
        if self.version == "v1" or verdict.allowed:
            self._send(claims, next_step)
            if self.version == "v1":
                self.shadow_verdict = verdict.as_json()
            return {"status": "sent", "verdict": "allowed" if verdict.allowed else "not checked"}
        self.blocks += 1
        if self.blocks >= MAX_BLOCKS:
            self.status = "withheld"
            if self.escalation is None:
                self.escalation = self._evidence_pack({"reason": "reply could not be proved",
                                                       "case_type": "unknown"})
            return {"status": "withheld", "reasons": verdict.reasons,
                    "note": "Reply withheld. The case went to a human with the receipts."}
        return {"status": "blocked", "reasons": verdict.reasons,
                "attempts_left": MAX_BLOCKS - self.blocks}

    def _send(self, claims: list[Claim], next_step: str) -> None:
        self.status = "sent"
        self.message = " ".join([c.text.strip() for c in claims] + [next_step.strip()]).strip()
        for c in claims:
            receipt = self.book.get(c.receipt_id)
            self.sent_claims.append({**c.as_json(), "receipt_ok": receipt.ok if receipt else None})

    @property
    def done(self) -> bool:
        return self.status in ("sent", "withheld")


def _complaint_message(scenario: Scenario) -> str:
    return (f"Complaint {scenario.complaint_id} from {scenario.customer_name}, received "
            f"{scenario.complained_at}:\n\n{scenario.narrative}")


def run_case(scenario: Scenario, version: str, *, chaos: ChaosFlags | None = None, client=None) -> dict:
    runner = _run_v2 if version == "v2" else _run_v1
    return runner(scenario, chaos, client or make_client())


@neatlogs.span(kind="AGENT", name="receipts.case", version="v1", tags=["prompt:v1"],
               capture_input=False, capture_output=False)
def _run_v1(scenario: Scenario, chaos: ChaosFlags | None, client) -> dict:
    return _loop(scenario, "v1", chaos, client)


@neatlogs.span(kind="AGENT", name="receipts.case", version="v2", tags=["prompt:v2"],
               capture_input=False, capture_output=False)
def _run_v2(scenario: Scenario, chaos: ChaosFlags | None, client) -> dict:
    return _loop(scenario, "v2", chaos, client)


def _loop(scenario: Scenario, version: str, chaos: ChaosFlags | None, client) -> dict:
    started = time.monotonic()
    world = open_world(scenario, chaos=chaos)
    case = Case(scenario, world, version)
    usage = Usage()
    tools = tool_specs(version)
    messages: list[dict] = [
        {"role": "system", "content": system_prompt(version)},
        {"role": "user", "content": _complaint_message(scenario)},
    ]
    transcript: list[dict] = []
    for _ in range(MAX_STEPS):
        response = complete(client, messages, tools)
        usage.add(response.usage)
        msg = response.choices[0].message
        calls = msg.tool_calls or []
        messages.append({
            "role": "assistant",
            "content": msg.content,
            **({"tool_calls": [{"id": c.id, "type": "function",
                                "function": {"name": c.function.name, "arguments": c.function.arguments}}
                               for c in calls]} if calls else {}),
        })
        if msg.content:
            transcript.append({"model": msg.content})
        if not calls:
            messages.append({"role": "user", "content": "Finish by calling send_reply."})
            continue
        for call in calls:
            name = call.function.name
            try:
                args = json.loads(call.function.arguments or "{}")
            except json.JSONDecodeError:
                args = {}
            if name == "send_reply":
                result = case.reply(args)
            elif name in TOOL_OPS and (name != "policy_lookup" or version == "v2"):
                result = _RUNNERS[TOOL_OPS[name]](case, args)
            else:
                result = {"ok": False, "error": f"unknown tool {name}"}
            transcript.append({"tool": name, "args": args, "result": result})
            messages.append({"role": "tool", "tool_call_id": call.id, "content": json.dumps(result)})
        if case.done:
            break
    if not case.done:
        case.status = "no_reply"
    ops = [r.op for r in case.book.receipts]
    graded = audit(
        scenario, world,
        sent_claims=case.sent_claims,
        reversed_called="sender.reverse" in ops,
        escalated=case.escalation is not None,
        reply_sent=case.status == "sent",
        policy_cited=any(c["assertion"] == "policy" for c in case.sent_claims),
    )
    final_verdict = case.attempts[-1]["verdict"] if case.attempts else None
    return {
        "seed": scenario.seed,
        "complaint_id": scenario.complaint_id,
        "pattern": scenario.pattern,
        "version": version,
        "model": model_name(),
        "trace_id": current_trace_id(),
        "status": case.status,
        "message": case.message,
        "claims_sent": case.sent_claims,
        "unproven_claims_sent": (sum(1 for c in (final_verdict or {}).get("claims", []) if not c["proved"])
                                 if case.status == "sent" else 0),
        "attempts": case.attempts,
        "blocks": case.blocks,
        "escalation": case.escalation,
        "receipts": [r.as_json() for r in case.book.receipts],
        "tool_order": ops,
        "transcript": transcript,
        "audit": graded.as_json(),
        "usage": usage.as_json(),
        "latency_s": round(time.monotonic() - started, 2),
    }

